# Long alternatives precede bounded short spellings; embedded natural words
# are excluded. A serialized URI is one exact value, not a domain-wide waiver.
LEGACY = re.compile(
    r"https://ai-engineering-orchestra\.dev/schemas/[A-Za-z0-9_.-]+"
    r"|AI Engineering Orchestra|ai-engineering-orchestra|engineering_orchestration"
    r"|ENGINEERING_ORCHESTRATION_[A-Z0-9_]*"
    r"|tool::(?:aeo|aio)-[A-Za-z0-9_:.-]*"
    r"|(?<![A-Za-z0-9])AIO-[0-9]+"
    r"|(?<![A-Za-z0-9])(?:AEO_|AIO_|aeo_|aio_)[A-Za-z0-9_]*"
    r"|(?<![A-Za-z0-9])(?:aeo-|aio-)[A-Za-z0-9_-]*"
    r"|(?<![A-Za-z0-9_])\.aio(?=$|[\s/\\`\"'])"
    r"|(?<![A-Za-z0-9_])(?:AEO|AIO|aeo|aio)(?![A-Za-z0-9_])"
)


class Reason(StrEnum):
    HISTORICAL_DURABLE_ID = "HISTORICAL_DURABLE_ID"
    HISTORICAL_COMPATIBILITY = "HISTORICAL_COMPATIBILITY"
    NEGATIVE_COMPATIBILITY_TEST = "NEGATIVE_COMPATIBILITY_TEST"
    HISTORICAL_PROVENANCE = "HISTORICAL_PROVENANCE"
    LAST_LEGACY_TASK_TRANSITION = "LAST_LEGACY_TASK_TRANSITION"


@dataclass(frozen=True, slots=True)
class _Allowance:
    path: str
    token: str
    scope: str
    anchor_sha256: str
    count: int
    reason: str
    justification: str
    removal: str

    @property
    def key(self):
        return self.path, self.token, self.scope, self.anchor_sha256


