def _living_path(path):
    if type(path) is not str or not path or "\\" in path or ":" in path:
        return False
    p = PurePosixPath(path)
    if p.is_absolute() or any(x in (".", "..") for x in p.parts):
        return False
    if p.as_posix() != path:
        return False
    return path in ROOT_FILES or (len(p.parts) > 1 and p.parts[0] in LIVING_ROOTS)


def _valid_allowance(item):
    return (
        type(item) is _Allowance and _living_path(item.path)
        and not any(c in item.path for c in "*?[]")
        and type(item.token) is str and LEGACY.fullmatch(item.token) is not None
        and type(item.scope) is str and bool(item.scope)
        and type(item.anchor_sha256) is str
        and re.fullmatch(r"[0-9a-f]{64}", item.anchor_sha256) is not None
        and type(item.count) is int and item.count > 0
        and item.reason in {r.value for r in Reason}
        and type(item.justification) is str and bool(item.justification.strip())
        and type(item.removal) is str and bool(item.removal.strip())
    )


def _node_position(node):
    """Exact AST range; columns are UTF-8 byte offsets, not character offsets."""
    return node.lineno, node.col_offset, node.end_lineno, node.end_col_offset


def _scopes(path, text):
    lines = text.splitlines()
    scopes = ["module"] * len(lines)
    spans = set()
    if path.endswith(".py"):
        tree = ast.parse(text, filename=path)
        def visit(node, parents=()):
            for child in ast.iter_child_nodes(node):
                if isinstance(child, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                    scope = parents + (child.name,)
                    for i in range(child.lineno - 1, child.end_lineno):
                        scopes[i] = ".".join(scope)
                    visit(child, scope)
                else:
                    visit(child, parents)
        visit(tree)
        if path == SELF_PATH:
            declarations = [node for node in tree.body if isinstance(node, ast.Assign)
                and any(isinstance(t, ast.Name) and t.id == "_ALLOWLIST" for t in node.targets)]
            if len(declarations) != 1 or not isinstance(declarations[0].value, ast.Tuple):
                raise ValueError("allowlist must have one explicit tuple declaration")
            declaration = declarations[0]
            if (len(declaration.targets) != 1 or not isinstance(declaration.targets[0], ast.Name)
                    or declaration.targets[0].id != "_ALLOWLIST"):
                raise ValueError("allowlist declaration cannot assign another target")
            for value in declaration.value.elts:
                if (not isinstance(value, ast.Call) or not isinstance(value.func, ast.Name)
                        or value.func.id != "_Allowance" or len(value.args) != 8 or value.keywords
                        or not all(isinstance(a, ast.Constant) for a in value.args)):
                    raise ValueError("allowlist data must be literal exact records")
                # Exempt literal metadata only, never its call, container, statement,
                # comments or any sibling sharing a physical source line.
                spans.update(_node_position(argument) for argument in value.args)
    elif path.endswith(".md"):
        heading = "document"
        for i, line in enumerate(lines):
            if re.match(r"^#{1,6} ", line): heading = line
            scopes[i] = heading
    else:
        scopes = ["serialized-document"] * len(lines)
    return scopes, spans


def _literal_policy_columns(text, lines, spans):
    """Exclude actual literal tokens, retaining comments inside merged AST ranges."""
    if not spans:
        return {}
    nodes_by_line = {}
    for position in spans:
        for number in range(position[0], position[2] + 1):
            nodes_by_line.setdefault(number, []).append(position)
    columns = {}
    for token in tokenize.generate_tokens(io.StringIO(text).readline):
        if token.type != tokenize.STRING:
            continue
        first, start_character = token.start
        last, end_character = token.end
        start = len(lines[first - 1][:start_character].encode("utf-8"))
        end = len(lines[last - 1][:end_character].encode("utf-8"))
        if not any((node_first, node_start) <= (first, start)
                   and (last, end) <= (node_last, node_end)
                   for node_first, node_start, node_last, node_end in nodes_by_line.get(first, ())):
            continue
        for number in range(first, last + 1):
            columns.setdefault(number, []).append((
                start if number == first else 0,
                end if number == last else len(lines[number - 1].encode("utf-8")),
            ))
    return columns


def occurrences(path, text):
    """Pure exact occurrence extraction with semantic scope and line digest."""
    if not _living_path(path): raise ValueError("path is outside the declared living scope")
    scopes, spans = _scopes(path, text)
    lines = text.splitlines()
    columns = _literal_policy_columns(text, lines, spans)
    found = Counter()
    for i, line in enumerate(lines, 1):
        anchor = sha256(line.strip().encode("utf-8")).hexdigest()
        for match in LEGACY.finditer(line):
            byte_start = len(line[:match.start()].encode("utf-8"))
            byte_end = len(line[:match.end()].encode("utf-8"))
            if any(start <= byte_start and byte_end <= end for start, end in columns.get(i, ())):
                continue
            found[(path, match.group(), scopes[i - 1], anchor)] += 1
    # Historical file names require their own exact allowance.
    for match in LEGACY.finditer(path):
        found[(path, match.group(), "file-path", sha256(path.encode()).hexdigest())] += 1
    return found


class _StaticStringLimitError(ValueError):
    """A literal assembly exceeds the checker's deterministic work bounds."""


_UNKNOWN_STATIC_STRING = object()


def _static_string(node, *, depth=0, budget=None):
    """Resolve literal assembly only; never evaluate names, calls or attributes."""
    if budget is None:
        budget = [256]
    budget[0] -= 1
    if budget[0] < 0:
        raise _StaticStringLimitError("static assembly exceeds the node bound")
    if depth > 20:
        raise _StaticStringLimitError("static assembly exceeds the depth bound")
    if isinstance(node, ast.Constant) and type(node.value) in (str, int, float, bool, type(None)):
        value = node.value
        if type(value) is int and value.bit_length() > 4096:
            raise _StaticStringLimitError("static integer exceeds the size bound")
        return value  # source literals need no new allocation or formatting
    elif isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        value = _static_string(node.operand, depth=depth + 1, budget=budget)
        if type(value) not in (int, float):
            raise ValueError("only signed numeric literals are supported")
        return -value if isinstance(node.op, ast.USub) else value
    elif isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        left = _static_string(node.left, depth=depth + 1, budget=budget)
        right = _static_string(node.right, depth=depth + 1, budget=budget)
        if type(left) is not str or type(right) is not str:
            raise ValueError("only literal string addition is supported")
        if len(left) + len(right) > 4096:
            raise _StaticStringLimitError("static assembly exceeds the text bound")
        value = left + right
    elif isinstance(node, ast.JoinedStr):
        if len(node.values) > 128:
            raise _StaticStringLimitError("static assembly exceeds the part bound")
        parts = [_static_string(part, depth=depth + 1, budget=budget) for part in node.values]
        if not all(type(part) is str for part in parts):
            raise ValueError("f-string parts must resolve to text")
        if sum(map(len, parts)) > 4096:
            raise _StaticStringLimitError("static assembly exceeds the text bound")
        value = "".join(parts)
    elif isinstance(node, ast.FormattedValue):
        value = _static_string(node.value, depth=depth + 1, budget=budget)
        if type(value) is str and len(value) > 4096:
            raise _StaticStringLimitError("formatted literal exceeds the text bound")
        if node.conversion == ord("s"):
            value = str(value)
        elif node.conversion == ord("r"):
            value = repr(value)
        elif node.conversion == ord("a"):
            value = ascii(value)
        elif node.conversion != -1:
            raise ValueError("unsupported literal conversion")
        spec = "" if node.format_spec is None else _static_string(node.format_spec, depth=depth + 1, budget=budget)
        if type(spec) is not str or len(spec) > 128:
            raise _StaticStringLimitError("literal format exceeds the specification bound")
        # Built-in format mini-language only, for exact primitive literal types.
        # No replacement-field evaluation or user-defined __format__ is possible.
        parsed = re.fullmatch(
            r"(?:(?:.)?[<>=^])?[+\- ]?z?\#?0?(?P<width>[0-9]*)[,_]?"
            r"(?:\.(?P<precision>[0-9]+))?[bcdeEfFgGosxX%]?", spec, re.DOTALL,
        )
        if parsed is None:
            raise ValueError("unsupported literal format")
        for dimension in (parsed.group("width"), parsed.group("precision")):
            digits = (dimension or "").lstrip("0")
            if len(digits) > 4 or (digits and int(digits) > 4096):
                raise _StaticStringLimitError("literal format exceeds the width/precision bound")
        value = format(value, spec)
    else:
        raise ValueError("assembly depends on unresolved Python")
    if type(value) is str and len(value) > 4096:
        raise _StaticStringLimitError("static assembly exceeds the text bound")
    return value


def _resolve_static_string(node):
    """Return complete static text or UNKNOWN; never execute unresolved Python."""
    try:
        value = _static_string(node)
    except _StaticStringLimitError:
        raise
    except (ValueError, TypeError, OverflowError):
        return _UNKNOWN_STATIC_STRING
    return value if type(value) is str else _UNKNOWN_STATIC_STRING


def check_namespace(files, allowances=(), *, complete=False):
    """Validate supplied text only; never reads directories or candidate Tasks."""
    errors, seen, actual = [], set(), Counter()
    for path, text in files.items():
        if not _living_path(path):
            errors.append(f"out-of-scope path: {path}")
            continue
        try: actual.update(occurrences(path, text))
        except (SyntaxError, ValueError) as error:
            errors.append(f"invalid source/policy: {path}: {error}")
            continue
        if path.endswith(".py"):
            policy_spans = _scopes(path, text)[1]
            def identity(token):
                if token.startswith("https://ai-engineering-orchestra.dev/schemas/"):
                    return "ai-engineering-orchestra"
                return token
            for node in ast.walk(ast.parse(text, filename=path)):
                if (
                    isinstance(node, ast.Constant) and type(node.value) is str
                    or isinstance(node, ast.JoinedStr)
                    or isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add)
                ):
                    if _node_position(node) in policy_spans:
                        continue  # already structurally validated literal policy data
                    try:
                        value = _resolve_static_string(node)
                    except _StaticStringLimitError as error:
                        errors.append(f"static assembly bound: {path}:{node.lineno}: {error}")
                        continue
                    if value is _UNKNOWN_STATIC_STRING:
                        continue  # lexical occurrences and known child expressions still apply
                    decoded = Counter(map(identity, LEGACY.findall(value)))
                    if not decoded:
                        continue
                    raw = ast.get_source_segment(text, node) or ""
                    # Adjacent schema-path literals retain their visibly written frozen
                    # host. Compare namespace identities rather than URI suffixes;
                    # occurrence allowances still bind the exact visible line.
                    visible = Counter(map(identity, LEGACY.findall(raw)))
                    if any(count > visible[token] for token, count in decoded.items()):
                        errors.append(f"hidden/folded legacy identity: {path}:{node.lineno}")
                modules = [a.name for a in node.names] if isinstance(node, ast.Import) else (
                    [node.module or ""] if isinstance(node, ast.ImportFrom) else [])
                if any(m == "engineering_orchestration" or m.startswith("engineering_orchestration.") for m in modules):
                    errors.append(f"legacy executable import: {path}:{node.lineno}")
    for item in allowances:
        if not _valid_allowance(item):
            errors.append("invalid or broad allowance")
            continue
        if item.key in seen: errors.append(f"duplicate allowance: {item.path}: {item.token}")
        seen.add(item.key)
        if complete or item.path in files:
            count = actual.pop(item.key, 0)
            if count != item.count:
                errors.append(f"stale/changed allowance: {item.path}: {item.scope}: {item.token}: {count}!={item.count}")
    errors.extend(f"unauthorized legacy identity: {p}: {scope}: {token} ({count})"
                  for (p, token, scope, anchor), count in sorted(actual.items()))
    return tuple(errors)


def living_files(root=ROOT):
    """Exact scoped Git manifest includes tracked and unstaged canonical files."""
    root = root.resolve()
    command = ["git", "ls-files", "-z", "--cached", "--others", "--exclude-standard", "--",
               *LIVING_ROOTS, *ROOT_FILES]
    output = subprocess.check_output(command, cwd=root)
    paths = sorted(set(output.decode("utf-8").split("\0")) - {""})
    files = {}
    for relative in paths:
        if not _living_path(relative): raise ValueError("manifest escaped living scope")
        path = root / relative
        if not path.exists(): continue  # unstaged deletion has no living content
        if path.resolve() != path.absolute() or path.is_symlink():
            raise ValueError("living manifest rejects symlink/junction traversal")
        files[relative] = path.read_text(encoding="utf-8")
    return files


def historical_task_id(value):
    if type(value) is not str or re.fullmatch(r"AIO-[0-9]{3}", value) is None: return False
    return 1 <= int(value[4:]) <= 59


def new_task_id(value):
    if type(value) is not str or re.fullmatch(r"ITRU-[0-9]{3,}", value) is None: return False
    number = int(value[5:])
    return number >= 60 and value[5:] == f"{number:03d}"


def new_task_candidate(value, directory_name=None, *, cutover_closed=False):
    if cutover_closed is not True or not new_task_id(value): return False
    return (
        type(directory_name) is str and (directory_name == value or directory_name.startswith(value + "-"))
        and "/" not in directory_name and "\\" not in directory_name
    )


class NamespaceGuardTests(unittest.TestCase):
    def allowance(self, path, text, reason=Reason.HISTORICAL_PROVENANCE.value):
        key, count = next(iter(occurrences(path, text).items()))
        return _Allowance(*key, count, reason, "Explicit historical fixture", "retain exact historical evidence")

    def test_canonical_and_natural_words_pass(self):
        text = 'ITRU itru ITRU_VERIFY_DEPTH tool::itru-native-repository-file-read::v1 ITRU-060\nchaotic caioid aeoexample aiogram\n'
        self.assertEqual(check_namespace({"core/sample.md": text}), ())

    def test_prospective_legacy_spellings_fail(self):
        for text in ("AI Engineering Orchestra", "ai-engineering-orchestra", "engineering_orchestration",
                     "tool::aeo-new-tool::v1", "ENGINEERING_ORCHESTRATION_NEW_SETTING", "AIO-060",
                     "aio verify", "~/.aio", "AEO runtime"):
            with self.subTest(text=text): self.assertTrue(check_namespace({"core/sample.md": text}))

    def test_historical_values_require_exact_context(self):
        for text in ('Historical AIO-058 introduced Entry.\n', 'AIO-059 is the final legacy Task.\n',
                     'Historical tool::aeo-native-repository-file-read::v1 evidence.\n'):
            item = self.allowance("core/history.md", text)
            self.assertEqual(check_namespace({"core/history.md": text}, (item,), complete=True), ())
            self.assertTrue(check_namespace({"core/new.md": text}, (item,), complete=True))
            self.assertTrue(check_namespace({"core/history.md": text + text}, (item,), complete=True))

    def test_copied_history_in_new_factory_fails(self):
        old = 'def read_history():\n    return "tool::aeo-native-repository-file-read::v1"\n'
        item = self.allowance("itru/sample.py", old)
        new = old.replace("read_history", "create_new_binding")
        self.assertTrue(check_namespace({"itru/sample.py": new}, (item,), complete=True))

    def test_stale_and_wildcard_exceptions_fail(self):
        from dataclasses import replace
        text = 'Historical AIO-058.\n'
        item = self.allowance("core/history.md", text)
        self.assertTrue(check_namespace({}, (item,), complete=True))
        self.assertTrue(check_namespace({"core/history.md": text}, (replace(item, path="core/*"),)))
        self.assertTrue(check_namespace({"core/history.md": text}, (item, item)))

    def test_legacy_import_and_constructed_identity_cannot_be_allowlisted(self):
        text = 'import engineering_orchestration\n'
        item = self.allowance("itru/sample.py", text)
        self.assertTrue(check_namespace({"itru/sample.py": text}, (item,)))
        text = 'name = "engineering" + "_orchestration"\n'
        self.assertTrue(check_namespace({"itru/sample.py": text}))

    def test_adjacent_and_escaped_python_literals_fail(self):
        for text in (
            'importlib.import_module("engineering" "_orchestration")',
            'tool = "tool::ae" "o-new-tool::v1"',
            'setting = "ENGINEERING_" "ORCHESTRATION_NEW_SETTING"',
            'schema = "https://ai-engineering-" "orchestra.dev/schemas/new.json"',
            r'name = "\x65ngineering_orchestration"',
        ):
            with self.subTest(text=text): self.assertTrue(check_namespace({"itru/sample.py": text}))

    def test_visible_frozen_schema_host_requires_exact_allowance(self):
        text = 'schema = ("https://ai-engineering-orchestra.dev/schemas/" "historical.schema.json")'
        item = self.allowance("itru/sample.py", text, Reason.HISTORICAL_DURABLE_ID.value)
        self.assertEqual(check_namespace({"itru/sample.py": text}, (item,), complete=True), ())
        self.assertTrue(check_namespace({"itru/sample.py": text}))

    def test_static_f_strings_reject_new_legacy_identity(self):
        legacy_import = next(item.token for item in _ALLOWLIST if item.token.endswith("_orchestration"))
        family = next(item.token for item in _ALLOWLIST if item.token.startswith("tool::")).split("::")[1].split("-")[0]
        prefix = next(item.token for item in _ALLOWLIST if item.token.endswith("-059")).split("-")[0]
        cases = (
            f'name = {legacy_import!r}',
            'name = f"{\'engineering\'}_orchestration"',
            f'name = f"tool::{{{family!r}}}-new-tool::v1"',
            'name = f"ENGINEERING_{\'ORCHESTRATION\'}_NEW_SETTING"',
            f'name = f"{prefix}-{{60:03d}}"',
            f'name = f"tool::{{{family!r}}}-{{unresolved}}"',
        )
        for text in cases:
            with self.subTest(text=text):
                self.assertTrue(check_namespace({"itru/sample.py": text}))

    def test_canonical_f_strings_and_unresolved_python_are_not_executed(self):
        for text in (
            'name = f"{\'itru\'}"',
            'name = f"tool::{\'itru\'}-new-tool::v1"',
            'name = f"ITRU_{\'NEW_SETTING\'}"',
            'name = f"ITRU-{60:03d}"',
            'name = f"{untrusted_call()}"',
        ):
            with self.subTest(text=text):
                self.assertEqual(check_namespace({"itru/sample.py": text}), ())
        node = ast.parse('f"{untrusted_call()}"', mode="eval").body
        with self.assertRaises(ValueError):
            _static_string(node)

    def test_visible_historical_f_string_still_requires_exact_allowance(self):
        historical = next(item.token for item in _ALLOWLIST if item.token.startswith("tool::"))
        text = f'def read_history():\n    return f"{historical}"\n'
        item = self.allowance("itru/sample.py", text, Reason.HISTORICAL_COMPATIBILITY.value)
        self.assertEqual(check_namespace({"itru/sample.py": text}, (item,), complete=True), ())
        self.assertTrue(check_namespace({"itru/sample.py": text}))
        self.assertTrue(check_namespace({"itru/other.py": text}, (item,), complete=True))
        changed = text.replace("read_history", "create_new_binding")
        self.assertTrue(check_namespace({"itru/sample.py": changed}, (item,), complete=True))

    def test_static_f_string_analysis_has_explicit_bounds(self):
        for text in ('f"{60:9999d}"', 'f"{untrusted_call()}"'):
            with self.subTest(text=text), self.assertRaises(ValueError):
                _static_string(ast.parse(text, mode="eval").body)
        self.assertTrue(check_namespace({"itru/sample.py": 'name = f"{60:9999d}"'}))

    def test_complete_static_expression_assembly_rejects_legacy_identity(self):
        family = next(item.token for item in _ALLOWLIST if item.token.startswith("tool::")).split("::")[1].split("-")[0]
        prefix = next(item.token for item in _ALLOWLIST if item.token.endswith("-059")).split("-")[0]
        expressions = (
            'f"{\'engineering\'}" + "_orchestration"',
            '"engineering" + f"_{\'orchestration\'}"',
            f'f"tool::{{{family!r}}}" + "-new-tool::v1"',
            '"ENGINEERING_" + f"{\'ORCHESTRATION\'}_NEW_SETTING"',
            f'"{prefix}-" + f"{{60:03d}}"',
            '("engineering" + "_") + "orchestration"',
            'f"{\'engineering\':>11}_orchestration"',
            'f"ENGINEERING_{\'ORCHESTRATION\':>13}_NEW_SETTING"',
            'f"{\'engineering\':>{11}}_orchestration"',
            'f"{\'engineering\':.11s}_orchestration"',
            'f"{\'engineering\'!s:>11}" + "_orchestration"',
        )
        for expression in expressions:
            with self.subTest(expression=expression):
                value = _resolve_static_string(ast.parse(expression, mode="eval").body)
                self.assertIs(type(value), str)
                self.assertIsNotNone(LEGACY.search(value))
                errors = check_namespace({"itru/sample.py": "name = " + expression})
                self.assertTrue(any("hidden/folded legacy identity" in error for error in errors))

    def test_canonical_complete_static_expression_assembly_passes(self):
        cases = (
            ('f"{\'itru\'}"', "itru"),
            ('"tool::" + "itru-native-repository-file-read::v1"', "tool::itru-native-repository-file-read::v1"),
            ('"ITRU_" + "VERIFY_DEPTH"', "ITRU_VERIFY_DEPTH"),
            ('"ITRU-" + f"{60:03d}"', "ITRU-060"),
            ('f"{\'itru\':>4s}"', "itru"),
            ('f"ITRU-{60:0>3d}"', "ITRU-060"),
            ('f"{\'itru\'}" + ("-" + f"{60:03d}")', "itru-060"),
        )
        for expression, expected in cases:
            with self.subTest(expression=expression):
                self.assertEqual(_resolve_static_string(ast.parse(expression, mode="eval").body), expected)
                self.assertEqual(check_namespace({"itru/sample.py": "name = " + expression}), ())

    def test_unknown_dynamic_expression_returns_unknown_without_execution(self):
        for expression in (
            'untrusted_call() + "_orchestration"',
            'f"{untrusted_call()}_orchestration"',
            'caller.attribute + "_orchestration"',
            'runtime_prefix + suffix',
            '"{0}".format(untrusted_call())',
            '"%s" % untrusted_call()',
            'f"{60:n}"',  # locale-dependent output is outside the static subset
        ):
            with self.subTest(expression=expression):
                self.assertIs(_resolve_static_string(ast.parse(expression, mode="eval").body), _UNKNOWN_STATIC_STRING)
                self.assertEqual(check_namespace({"itru/sample.py": "name = " + expression}), ())

        class CallerObject:
            def __format__(self, spec):
                raise AssertionError("user formatting was executed")

            def __add__(self, other):
                raise AssertionError("user addition was executed")

        value = ast.Constant(value=CallerObject())
        formatted = ast.JoinedStr(values=[ast.FormattedValue(value=value, conversion=-1)])
        added = ast.BinOp(left=value, op=ast.Add(), right=ast.Constant(value="itru"))
        for node in (formatted, added):
            self.assertIs(_resolve_static_string(node), _UNKNOWN_STATIC_STRING)

    def test_assembled_visible_history_requires_exact_approved_context(self):
        historical = next(item.token for item in _ALLOWLIST if item.token.startswith("tool::"))
        text = f'def read_history():\n    return f"{historical}" + ""\n'
        item = self.allowance("itru/sample.py", text, Reason.HISTORICAL_COMPATIBILITY.value)
        self.assertEqual(check_namespace({"itru/sample.py": text}, (item,), complete=True), ())
        self.assertTrue(check_namespace({"itru/sample.py": text}))
        self.assertTrue(check_namespace({"itru/other.py": text}, (item,), complete=True))
        self.assertTrue(check_namespace({"itru/sample.py": text.replace("read_history", "create_new_binding")}, (item,), complete=True))

    def test_complete_static_expression_work_and_format_bounds(self):
        expressions = (
            'f"{\'itru\':>9999}"',
            'f"{1:.9999f}"',
            '"itru"' + ' + ""' * 30,
            'f"' + "{'x'}" * 129 + '"',
        )
        for expression in expressions:
            with self.subTest(expression=expression):
                with self.assertRaises(_StaticStringLimitError):
                    _resolve_static_string(ast.parse(expression, mode="eval").body)
                self.assertTrue(check_namespace({"itru/sample.py": "name = " + expression}))

    def policy_fixture(self):
        item = _ALLOWLIST[0]
        fields = (item.path, item.token, item.scope, item.anchor_sha256, item.count,
                  item.reason, item.justification, item.removal)
        return "_ALLOWLIST = (\n    _Allowance(" + ", ".join(map(repr, fields)) + "),\n)"

    def test_policy_tuple_same_line_bypass_is_rejected(self):
        expression = 'f"{\'engineering\'}" + "_orchestration"'
        original = (ROOT / SELF_PATH).read_text(encoding="utf-8")
        self.assertEqual(check_namespace({SELF_PATH: original}, _ALLOWLIST), ())
        declaration = next(node for node in ast.parse(original).body
            if isinstance(node, ast.Assign)
            and any(isinstance(target, ast.Name) and target.id == "_ALLOWLIST" for target in node.targets))
        lines = original.splitlines(keepends=True)
        line = lines[declaration.end_lineno - 1]
        column = len(line.encode("utf-8")[:declaration.end_col_offset].decode("utf-8"))
        lines[declaration.end_lineno - 1] = line[:column] + "; LIVE_PRODUCT = " + expression + line[column:]
        errors = check_namespace({SELF_PATH: "".join(lines)}, _ALLOWLIST)
        self.assertTrue(any("hidden/folded legacy identity" in error for error in errors))
        self.assertFalse(any("stale/changed allowance" in error for error in errors))

